    raise ValueError('Already iterated all files')

if subfiles is None:
    subfiles = [name for name, _ in self.iter_files()]

if isinstance(tags, str):
    tags = [tags]

for subfile, handle in self.iter_files(subfiles):
    depth = 0
    for event, elem in ET.iterparse(handle, events=('start', 'end')):
        if event == 'start':
            depth += 1
        if event == 'end':
            depth -= 1
        if tags is None or elem.tag in tags:
            yield subfile, elem, depth

        if not need_children and event == 'end' and depth == 0:
