        for event, elem in ET.iterparse(handle, events=('start', 'end')):
            if event == 'start':
                depth = elem.getroottree().getpath(elem).count('/')
                if tags is None or elem.tag in tags:
                    yield subfile, elem, depth
            if not need_children and event == 'end':
                elem.clear()
            while elem.getprevious() is not None:
                del elem.getparent()[0]
        self.did_iter_all = True
else:
    if subfiles is None:
        if self.did_iter_all:
            raise BadOOXML(self.filename, 'all subfiles already parsed')
        subfiles = [name for name, _ in self.iter_files()]
    else:
        subfiles = set(subfiles)
    for subfile, handle in self.iter_files(subfiles):
        if subfile is None:
            subfile = self.filename
        for event, elem in ET.iterparse(handle, events=('start', 'end')):
            if event == 'start':
                depth = elem.getroottree().getpath(elem).count('/')
                if tags is None or elem.tag in tags:
