    if subfiles:
        raise BadOOXML(self.filename, 'xml has no subfiles')
    if tags:
        raise BadOOXML(self.filename, 'xml has no tags')
    if need_children:
        raise BadOOXML(self.filename, 'xml has no children')
    for subfile, handle in self.iter_files():
        yield subfile, ET.parse(handle).getroot(), 0
