for bucket in paginated(storage.get_all, limit=100, sorting=OLDEST_FIRST):
    bucket_id = bucket["id"]
    total_records = 0
    total_size = 0
    total_collections = 0

    for collection in storage.get_all("collection", parent_id=bucket_id):
        collection_id = collection["id"]
        collection_records = storage.get_all("record", parent_id=collection_id)
        total_records += len(collection_records)
        total_collections += 1
        for record in collection_records:
            total_size += record_size(record)

    quota = {
        "quota": {
            "record_count": total_records,
            "storage_size": total_size,
            "collection_count": total_collections
        }
    }

    if not dry_run:
        storage.update("bucket", quota, parent_id=bucket_id)

    logger.info(f"Bucket {bucket_id} - Records: {total_records}, Size: {total_size}, Collections: {total_collections}")

