def detect_sequence(seq, i, j, token, space, ascending):
    sequences.append({
        'pattern': 'sequence',
        'i': i,
        'j': j,
        'token': token,
        'sequence_name': seq,
        'sequence_space': space,
        'ascending': ascending
    })

# Detect lowercase letter sequences
for i in range(len(password)):
    j = i
    while j < len(password) - 1 and ord(password[j + 1]) - ord(password[j]) == 1 and password[j] in lower:
        j += 1
    if j - i > 1:
        detect_sequence('lower', i, j, password[i:j + 1], 'abcdefghijklmnopqrstuvwxyz', True)

# Detect uppercase letter sequences
for i in range(len(password)):
    j = i
    while j < len(password) - 1 and ord(password[j + 1]) - ord(password[j]) == 1 and password[j] in upper:
        j += 1
    if j - i > 1:
        detect_sequence('upper', i, j, password[i:j + 1], 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', True)

# Detect digit sequences
for i in range(len(password)):
    j = i
    while j < len(password) - 1 and ord(password[j + 1]) - ord(password[j]) == 1 and password[j] in digits:
        j += 1
    if j - i > 1:
        detect_sequence('digits', i, j, password[i:j + 1], '0123456789', True)

# Detect other unicode sequences
for i in range(len(password)):
    j = i
    while j < len(password) - 1 and ord(password[j + 1]) - ord(password[j]) == 1:
        j += 1
    if j - i > 1:
        detect_sequence('unicode', i, j, password[i:j + 1], 'unicode', True)

return sequences

