    delta = ord(password[j]) - ord(password[i])
    if delta == 1 or delta == -1:
        sequence_name = 'lower'
        sequence_space = 26
        if password[i].isupper() and password[j].isupper():
            sequence_name = 'upper'
        elif password[i].isdigit() and password[j].isdigit():
            sequence_name = 'digits'
            sequence_space = 10
        elif not password[i].isalnum() or not password[j].isalnum():
            sequence_name = 'unicode'
            sequence_space = 0
        while j < len(password) - 1:
            next_delta = ord(password[j + 1]) - ord(password[j])
            if next_delta == delta:
                j += 1
            else:
                break
        if j - i > 1:
            matches.append({
                'pattern': 'sequence',
                'i': i,
                'j': j,
                'token': password[i:j + 1],
                'sequence_name': sequence_name,
                'sequence_space': sequence_space,
                'ascending': delta == 1,
            })
    i = j

return matches

