class ReadTransaction:
    def __init__(self, file_memory):
        self.file_memory = file_memory

    def __enter__(self):
        self.file_memory._lock.reader_lock.acquire()

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.file_memory._lock.reader_lock.release()

return ReadTransaction(self)

