def _schema_item_key(schema_item: SchemaItem) -> str:
    return schema_item.name

def _sort_key(schema_item: SchemaItem) -> str:
    return "%s.%s" % (
        schema_item.__class__.__name__,
        schema_item_key(schema_item),
    )

def _compare_tables(
    source: Dict[str, SchemaItem], target: Dict[str, SchemaItem]
) -> List[ops.TableOps]:
    source_set = set(source)
    target_set = set(target)

    added = source_set - target_set
    removed = target_set - source_set
    common = source_set.intersection(target_set)

    added_tables = [source[name] for name in added]
    removed_tables = [target[name] for name in removed]

    return [
        ops.TableOps(
            table=table,
            operations=[
                ops.AddTableOp(table=table)
            ],
        )
        for table in added_tables
    ] + [
        ops.TableOps(
            table=table,
            operations=[
                ops.DropTableOp(table=table)
            ],
        )
        for table in removed_tables
    ] + [
        compare.compare_tables(source[name], target[name])
        for name in common
    ]

