        elif c == "-":
            perms.append("")
        else:
            raise ValueError("Invalid permission string")
    elif i % 3 == 2:
        if c == "x":
            perms.append("x")
        elif c == "-":
            perms.append("")
        else:
            raise ValueError("Invalid permission string")
user = "".join(perms[:3])
group = "".join(perms[3:6])
other = "".join(perms[6:])
return cls(user=user, group=group, other=other)

