if isinstance(output_file, str):
    file_extension = os.path.splitext(output_file)[1].lower()

    if file_extension == ".html":
        with open(output_file, "w", encoding="utf-8") as f:
            self.generate_report(f, "html", file_info=file_info)
    elif file_extension == ".json":
        with open(output_file, "w", encoding="utf-8") as f:
            self.generate_report(f, "json", file_info=file_info)
    elif file_extension == ".gz":
        with gzip.open(output_file, "wt", encoding="utf-8") as f:
            self.generate_report(f, "json", file_info=file_info)
    else:
        raise ValueError("Unsupported file format")

    self.final_messages.append(("view_command", {"output_file": os.path.abspath(output_file)}))
    color_print("Report saved to " + os.path.abspath(output_file))
elif isinstance(output_file, TextIO):
    file_extension = os.path.splitext(output_file.name)[1].lower()

    if file_extension == ".html":
        self.generate_report(output_file, "html", file_info=file_info)
    elif file_extension == ".json":
        self.generate_report(output_file, "json", file_info=file_info)
    elif file_extension == ".gz":
        with gzip.open(output_file, "wt", encoding="utf-8") as f:
            self.generate_report(f, "json", file_info=file_info)
    else:
        raise ValueError("Unsupported file format")

    self.final_messages.append(("view_command", {"output_file": os.path.abspath(output_file.name)}))
    color_print("Report saved to " + os.path.abspath(output_file.name))

for message, data in self.final_messages:
