    if self.statedb.should_stop():
        logger.info("Stop signal received, exiting")
        break

    # Process each source
    for name, source in self.sources.items():
        logger.debug(f"Processing source '{name}'")
        try:
            for artifact in source.run():
                if not self._is_whitelisted(artifact):
                    self.process_artifact(artifact)
        except Exception as e:
            logger.exception(f"Error processing source '{name}': {e}")

    # Sleep for a bit
    time.sleep(self.config.poll_interval())

# Clean up
