def parse_toc_hook(tokens, state, content):
    toc = []
    for token in tokens:
        if token['type'] == 'heading_open':
            toc_level = int(token['tag'][1])
            if min_level <= toc_level <= max_level:
                token['toc'] = True
                token['anchor'] = heading_id(striptags(content[token['index'] + 1]))
                if toc_level > md.toc_level:
                    toc.append({'content': striptags(content[token['index'] + 1]), 'anchor': token['anchor'], 'children': []})
                    if md.toc_level:
                        toc[-2]['children'] = [toc[-1]]
                elif toc_level == md.toc_level:
                    toc[-1]['children'].append({'content': striptags(content[token['index'] + 1]), 'anchor': token['anchor'], 'children': []})
                else:
                    while toc and toc[-1]['content'] != striptags(content[token['index'] + 1]):
                        toc.pop()
                    if toc:
                        toc[-1]['children'].append({'content': striptags(content[token['index'] + 1]), 'anchor': token['anchor'], 'children': []})
                md.toc_level = toc_level
    md.toc_tokens = toc

