class TocTreeprocessor:
    def __init__(self, md):
        self.md = md

    def run(self, root):
        toc = []
        for element in root:
            if element.tag == 'h' and min_level <= int(element.get('level')) <= max_level:
                toc.append({
                    'id': heading_id(element.text) if heading_id else element.get('id'),
                    'level': int(element.get('level')),
                    'children': []
                })
            elif toc and element.tag == 'p':
                toc[-1]['children'].append({
                    'id': None,
                    'level': 0,
                    'children': []
                })
        save_toc(toc)
        return root

md.toc_hook = toc_hook

