return paths

paths = []
if isinstance(content, str):
    lines = content.split('\n')
else:
    lines = content

for line in lines:
    path = extract_exec_path(line) or extract_open_path(line) or extract_stat_path(line)
    if path:
        if existing_only and os.path.exists(path) and not os.path.isdir(path):
            paths.append(path)
        elif not existing_only:
            paths.append(path)

return paths
